  private def findAtPath(value: JsonValue, parts: List[String]): Option[JsonValue] = parts match {
    case Nil => Some(value)
    case head :: tail =>
      value match {
        case JsonValue.JsonObject(fields) =>
          fields.collectFirst { case (`head`, fieldValue) => fieldValue }.flatMap(findAtPath(_, tail))
