final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  def this(
      lowercase: Boolean,
      minLength: Int,
      maxLength: Int,
      stripPunctuation: Boolean
  ) = this(lowercase, minLength, Some(maxLength), stripPunctuation)

  def tokenize(text: String): List[Token] =
    splitWords(text).zipWithIndex.flatMap { case (word, index) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> index, "original" -> word)
        )
      }
    }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)
  def tokenize_to_strings(text: String): List[String] = tokenizeToStrings(text)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val (_, results) = splitWords(text).foldLeft(0 -> List.empty[(String, Int, Int)]) {
      case ((currentPos, acc), word) =>
        val start = text.indexOf(word, currentPos)
        val end = start + word.length
        val nextAcc = processToken(word)
          .map(processed => acc :+ (processed, start, end))
          .getOrElse(acc)
        end -> nextAcc
    }
    results
  }

  def tokenize_with_positions(text: String): List[(String, Int, Int)] =
    tokenizeWithPositions(text)

  def countTokens(text: String): Int = tokenize(text).length
  def count_tokens(text: String): Int = countTokens(text)

  private def processToken(rawWord: String): Option[String] = {
    val stripped = if (stripPunctuation) rawWord.dropWhile(punctuation).reverse.dropWhile(punctuation).reverse else rawWord
    val normalized = if (lowercase) stripped.toLowerCase else stripped
    val sized = maxLength.filter(limit => normalized.length > limit).fold(normalized)(normalized.take)

    Option.when(sized.nonEmpty && sized.length >= minLength)(sized)
  }

  private def splitWords(text: String): List[String] = text.trim match {
    case "" => List.empty[String]
    case _ => text.trim.split("\\s+").toList
  }
}

