object JsonValue {
  case object JsonNull extends JsonValue
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: BigDecimal) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case class JsonArray(values: Vector[JsonValue]) extends JsonValue
  case class JsonObject(fields: Vector[(String, JsonValue)]) extends JsonValue

  def fromAny(value: Any): JsonValue = value match {
    case null => JsonNull
    case json: Json => fromCirce(json)
    case string: String => JsonString(string)
    case boolean: Boolean => JsonBoolean(boolean)
    case int: java.lang.Integer => JsonNumber(BigDecimal(int.intValue()))
    case long: java.lang.Long => JsonNumber(BigDecimal(long.longValue()))
    case double: java.lang.Double => JsonNumber(BigDecimal(double.doubleValue()))
    case float: java.lang.Float => JsonNumber(BigDecimal.decimal(float.toDouble))
    case decimal: BigDecimal => JsonNumber(decimal)
    case decimal: JBigDecimal => JsonNumber(BigDecimal(decimal))
    case values: Iterable[_] => JsonArray(values.toVector.map(fromAny))
    case fields: Map[_, _] =>
      JsonObject(fields.toVector.map { case (key, fieldValue) => key.toString -> fromAny(fieldValue) })
    case other => JsonString(other.toString)
  }

  def fromCirce(json: Json): JsonValue =
    json.fold(
      jsonNull = JsonNull,
      jsonBoolean = JsonBoolean,
      jsonNumber = number => JsonNumber(number.toBigDecimal.getOrElse(BigDecimal(number.toString))),
      jsonString = JsonString,
      jsonArray = values => JsonArray(values.map(fromCirce).toVector),
      jsonObject = obj => JsonObject(obj.toIterable.toVector.map { case (key, value) => key -> fromCirce(value) })
    )
}

