  def tokenize_path(value: JsonValue, path: String): Option[Token] = tokenizePath(value, path)
  def tokenize_path(value: Json, path: String): Option[Token] = tokenizePath(value, path)

  private def findAtPath(value: JsonValue, parts: List[String]): Option[JsonValue] = parts match {
    case Nil => Some(value)
    case head :: tail =>
      value match {
        case JsonValue.JsonObject(fields) =>
          fields.collectFirst { case (`head`, fieldValue) => fieldValue }.flatMap(findAtPath(_, tail))
