  case class JsonNumber(value: BigDecimal) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case class JsonArray(values: Vector[JsonValue]) extends JsonValue
  case class JsonObject(fields: Vector[(String, JsonValue)]) extends JsonValue

  def fromAny(value: Any): JsonValue = value match {
    case null => JsonNull
    case json: Json => fromCirce(json)
    case string: String => JsonString(string)
    case boolean: Boolean => JsonBoolean(boolean)
    case int: java.lang.Integer => JsonNumber(BigDecimal(int.intValue()))
    case long: java.lang.Long => JsonNumber(BigDecimal(long.longValue()))
    case double: java.lang.Double => JsonNumber(BigDecimal(double.doubleValue()))
