    case fields: Map[_, _] =>
      JsonObject(fields.toVector.map { case (key, fieldValue) => key.toString -> fromAny(fieldValue) })
    case other => JsonString(other.toString)
  }

  def fromCirce(json: Json): JsonValue =
    json.fold(
      jsonNull = JsonNull,
      jsonBoolean = JsonBoolean,
      jsonNumber = number => JsonNumber(number.toBigDecimal.getOrElse(BigDecimal(number.toString))),
      jsonString = JsonString,
      jsonArray = values => JsonArray(values.map(fromCirce).toVector),
      jsonObject = obj => JsonObject(obj.toIterable.toVector.map { case (key, value) => key -> fromCirce(value) })
