  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val (_, results) = splitWords(text).foldLeft(0 -> List.empty[(String, Int, Int)]) {
      case ((currentPos, acc), word) =>
        val start = text.indexOf(word, currentPos)
        val end = start + word.length
        val nextAcc = processToken(word)
          .map(processed => acc :+ (processed, start, end))
          .getOrElse(acc)
        end -> nextAcc
