  def this(
      lowercase: Boolean,
      minLength: Int,
      maxLength: Int,
      stripPunctuation: Boolean
  ) = this(lowercase, minLength, Some(maxLength), stripPunctuation)

  def tokenize(text: String): List[Token] =
    splitWords(text).zipWithIndex.flatMap { case (word, index) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> index, "original" -> word)
        )
      }
